import { serve } from '../../scripts/serve.js';
import { fileURLToPath } from 'node:url';
const __dirname = fileURLToPath(new URL('.', import.meta.url));
import {chromium} from 'playwright';
import assert from 'node:assert/strict';
import path from 'node:path';
import os from 'node:os';
import fs from 'node:fs';
import {pathToFileURL} from 'node:url';
const server = await serve();
const url = server.url;
const screenshots=process.env.BENTO_SCREENSHOT_DIR || fs.mkdtempSync(path.join(os.tmpdir(),'bento-records-'));
fs.mkdirSync(screenshots,{recursive:true});
let browser;
(async()=>{
 browser=await chromium.launch({headless:true,...(process.env.BENTO_CHROME_PATH ? {executablePath:process.env.BENTO_CHROME_PATH} : {})});
 const page=await browser.newPage({viewport:{width:1024,height:900},acceptDownloads:true});
 page.setDefaultTimeout(8000);
 const errors=[];page.on('pageerror',e=>errors.push(e.message));
 const stored=()=>page.evaluate(()=>JSON.parse(localStorage.getItem('bento.prototype.workspace.v4')));
 const findTask=(snapshot,title)=>Object.values(snapshot.workspace.records).find(record=>record.database==='db-todos'&&record.title===title);
 const append=async(body,label='Meeting Markdown')=>{
  await page.getByRole('button',{name:'Write a note…',exact:true}).click();
  await page.getByRole('textbox',{name:label,exact:true}).fill(body);
 };
 await page.goto(url);
 await page.getByRole('button',{name:'Meeting note',exact:true}).click();
 assert.equal(await page.getByRole('button',{name:'Read',exact:true}).count(),0);
 assert.equal(await page.getByRole('button',{name:'Write Markdown',exact:true}).count(),0);
 assert.equal(await page.locator('[data-block-source]').count(),0);
 await append('- [ ] New direct action (due 2026-10-21)\n  - [ ] Nested action\n\n```md\n- [ ] Fenced sample\n```\n\n    - [ ] Indented sample\n');
 assert.match(await page.locator('#b-task-count').innerText(),/5 linked todos/);
 let snapshot=await stored();
 const created=findTask(snapshot,'New direct action');
 assert.ok(created);
 assert.equal(created.properties['field-task-due'],'2026-10-21');
 assert.equal(findTask(snapshot,'Fenced sample'),undefined);
 assert.doesNotMatch(snapshot.workspace.records.coordination.body,/bento-ref/);
 await page.getByRole('button',{name:'Open New direct action',exact:true}).click();
 await append('# Working notes\n\nKeep this context attached to the task.\n','Todo Markdown');
 await page.getByRole('checkbox',{name:'Completed',exact:true}).click();
 await page.getByRole('textbox',{name:'Todo title',exact:true}).fill('Review the new comments');
 await page.getByRole('button',{name:'Save properties',exact:true}).click();
 const downloadPromise=page.waitForEvent('download');
 await page.getByRole('button',{name:'Download Markdown',exact:true}).click();
 const download=await downloadPromise;
 assert.equal(download.suggestedFilename(),created.id+'.md');
 const markdown=fs.readFileSync(await download.path(),'utf8');
 assert.doesNotMatch(markdown,/^database:/m);
 assert.match(markdown,/Keep this context attached/);
 assert.match(markdown,/option-done/);
 await page.locator('#bento-workflow').screenshot({path:path.join(screenshots,'todo.png')});
 await page.getByRole('button',{name:'Back to Weekly coordination',exact:true}).click();
 assert.equal(await page.getByRole('checkbox',{name:'Complete Review the new comments',exact:true}).isChecked(),true);
 await page.getByRole('checkbox',{name:'Complete Review the new comments',exact:true}).click();
 await page.getByRole('button',{name:'Daily overview',exact:true}).click();
 assert.equal(await page.getByRole('checkbox',{name:'Complete Review the new comments',exact:true}).isChecked(),false);
 await page.getByRole('button',{name:'Review the new comments',exact:true}).click();
 assert.match(await page.locator('#b-reading').innerText(),/Keep this context attached/);
 await page.reload();
 assert.match(await page.locator('#b-reading').innerText(),/Keep this context attached/);
 await page.getByRole('button',{name:'Back to Weekly coordination',exact:true}).click();
 // Editing a rendered paragraph exposes only that block's Markdown.
 await page.locator('[data-start]').filter({hasText:'Discussed review comments'}).click();
 const source=page.getByRole('textbox',{name:'Meeting Markdown',exact:true});
 await source.fill('**Revised discussion** with a [reference](creek.md).\n\n');
 await source.press('Escape');
 await page.locator('#b-reading strong').filter({hasText:'Revised discussion'}).waitFor();
 // Clicking formatted text keeps a nearby caret rather than jumping to the end.
 await page.locator('#b-reading strong').filter({hasText:'Revised discussion'}).click({position:{x:2,y:8}});
 assert.equal(await source.evaluate(input=>input.selectionStart < input.value.length / 2),true);
 await source.press('Escape');
 assert.equal(await page.locator('[data-start]:focus').count(),1);
 await page.keyboard.press('Enter');
 await source.evaluate(input=>input.setSelectionRange(0,0));
 await source.press('ArrowUp');
 assert.match(await source.inputValue(), /Discussion & decisions/);
 await source.evaluate(input=>input.setSelectionRange(input.value.length,input.value.length));
 await source.press('ArrowDown');
 assert.match(await source.inputValue(), /Revised discussion/);
 assert.equal(await source.evaluate(input=>input.selectionStart),0);
 await source.press('Escape');
 const formatted=page.locator('#b-reading strong').filter({hasText:'Revised discussion'});
 await formatted.evaluate(element=>{const range=document.createRange();range.selectNodeContents(element);const selection=getSelection();selection.removeAllRanges();selection.addRange(range);});
 await formatted.dispatchEvent('click');
 assert.equal(await page.locator('[data-block-source]').count(),0);
 await page.evaluate(()=>getSelection().removeAllRanges());

 // [] + space converts before a title exists. Typing continues in the formatted task.
 await page.getByRole('button',{name:'Write a note…',exact:true}).click();
 await source.pressSequentially('[] ');
 let focused=page.locator('[data-task-title]:focus');
 assert.equal(await focused.count(),1);
 assert.equal(await page.locator('[data-block-source]').count(),0);
 await focused.pressSequentially('Typing action');
 await focused.press('Enter');
 await page.locator('[data-task-title]:focus').pressSequentially('Second typed action');
 snapshot=await stored();
 assert.ok(findTask(snapshot,'Typing action'));
 assert.ok(findTask(snapshot,'Second typed action'));
 const firstId=findTask(snapshot,'Typing action').id;
 // Inline rename keeps identity and copied links keep one canonical record.
 const firstInput=page.locator('[data-task-title]');
 const targetInput=await firstInput.evaluateAll(elements=>elements.findIndex(element=>element.value==='Typing action'));
 await firstInput.nth(targetInput).fill('Typing action revised');
 assert.equal(findTask(await stored(),'Typing action revised').id,firstId);
 const linked=(await stored()).workspace.records.coordination.body.split('\n').find(line=>line.includes(firstId+'.md'));
 await append(linked+'\n');
 assert.equal(Object.values((await stored()).workspace.records).filter(record=>record.id===firstId).length,1);
 await page.getByRole('button',{name:'Preview agent suggestion',exact:true}).click();
 await page.getByRole('button',{name:'Insert Markdown checkbox',exact:true}).click();
 assert.ok(findTask(await stored(),'Prepare an agenda for the next coordination meeting'));
 await page.getByRole('button',{name:'Undo last change',exact:true}).click();
 assert.equal(findTask(await stored(),'Prepare an agenda for the next coordination meeting'),undefined);
 await append('<img src=x onerror="window.bentoBad=true">\n');
 await page.getByRole('textbox',{name:'Meeting Markdown',exact:true}).press('Escape');
 assert.equal(await page.evaluate(()=>window.bentoBad),undefined);
 assert.equal(await page.locator('#b-reading img').count(),0);
 await page.locator('#bento-workflow').screenshot({path:path.join(screenshots,'meeting.png')});
 for(const width of [320,736,1024]){
  await page.setViewportSize({width,height:900});
  assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true,'Overflow '+width);
 }
 await page.getByRole('button',{name:'Daily overview',exact:true}).click();
 await page.locator('#bento-workflow').screenshot({path:path.join(screenshots,'daily.png')});
 assert.deepEqual(errors,[]);
 console.log('Passed unified live editing, checkbox shortcuts/typing/continuation, inline renames, todo notes, completion, exports, reload, copied links, agent undo, safe HTML, and responsive widths.');
 const context=await browser.newContext({timezoneId:'America/Los_Angeles',viewport:{width:1024,height:900}});
 const profilePage=await context.newPage();
 await profilePage.clock.install({time:new Date('2026-10-19T19:00:00Z')});
 await profilePage.addInitScript(()=>{window.bentoSent=[];window.openai={setWidgetState:async value=>{window.bentoSent.push(value);}};});
 await profilePage.goto(url);
 await profilePage.getByRole('heading',{name:'Hello, Makena',exact:true}).waitFor();
 await profilePage.getByRole('button',{name:'Profile',exact:true}).click();
 assert.equal(await profilePage.getByLabel('Last name',{exact:true}).inputValue(),'');
 assert.equal(await profilePage.getByLabel('Birthday',{exact:true}).inputValue(),'');
 await profilePage.getByLabel('First name',{exact:true}).fill('Makena');
 await profilePage.getByLabel('Last name',{exact:true}).fill('Example');
 await profilePage.getByLabel('Birthday',{exact:true}).fill('1990-10-19');
 await profilePage.getByRole('button',{name:'Save profile',exact:true}).click();
 await profilePage.getByRole('heading',{name:'hbd Makena!',exact:true}).waitFor();
 assert.match(await profilePage.locator('#b-status').innerText(),/Profile saved/);
 const saved=await profilePage.evaluate(()=>JSON.parse(localStorage.getItem('bento.prototype.profile.v1')));
 assert.deepEqual(saved,{version:1,firstName:'Makena',lastName:'Example',birthday:'1990-10-19'});
 const outbound=await profilePage.evaluate(()=>JSON.stringify(window.bentoSent));
 assert.equal(outbound.includes('1990-10-19'),false);
 assert.equal(outbound.includes('Example'),false);
 await profilePage.reload();
 await profilePage.getByRole('heading',{name:'hbd Makena!',exact:true}).waitFor();
 await profilePage.clock.setSystemTime(new Date('2026-10-20T19:00:00Z'));
 await profilePage.clock.runFor(60_001);
 await profilePage.getByRole('heading',{name:'Hello, Makena',exact:true}).waitFor();
 const dateCases=await profilePage.evaluate(async()=>{
  const {default: BentoProfile} = await import('./profile.js');
   const profile={version:1,firstName:'Sam',lastName:'',birthday:'2000-02-29'};
   return [
     BentoProfile.greeting(profile,new Date('2028-02-29T12:00:00')),
     BentoProfile.greeting(profile,new Date('2027-02-28T12:00:00')),
     BentoProfile.validate({...profile,birthday:'2001-02-29'}),
     BentoProfile.validate({...profile,birthday:'2100-01-01'}),
     BentoProfile.validate({...profile,firstName:'   '})
   ];
 });
 assert.deepEqual(dateCases,['hbd Sam!','Hello, Sam',false,false,false]);
 await profilePage.getByRole('button',{name:'Profile',exact:true}).click();
 await profilePage.getByLabel('First name',{exact:true}).fill('Maki');
 await profilePage.getByLabel('Birthday',{exact:true}).fill('');
 await profilePage.getByRole('button',{name:'Save profile',exact:true}).click();
 await profilePage.getByRole('heading',{name:'Hello, Maki',exact:true}).waitFor();
 await profilePage.getByRole('button',{name:'Profile',exact:true}).click();
 for(const width of [320,736,1024]){
   await profilePage.setViewportSize({width,height:900});
   assert.equal(await profilePage.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true,'Profile overflow '+width);
 }
 await profilePage.locator('#bento-workflow').screenshot({path:path.join(screenshots,'profile.png')});
 await profilePage.getByRole('button',{name:'Back to overview',exact:true}).click();
 await profilePage.locator('#bento-workflow').screenshot({path:path.join(screenshots,'profile-daily.png')});
 const blocked=await context.newPage();
 await blocked.addInitScript(()=>Object.defineProperty(window,'localStorage',{get(){throw new Error('Unavailable');}}));
 await blocked.goto(url);
 await blocked.getByRole('button',{name:'Profile',exact:true}).click();
 await blocked.getByLabel('First name',{exact:true}).fill('Session user');
 await blocked.getByRole('button',{name:'Save profile',exact:true}).click();
 await blocked.getByRole('heading',{name:'Hello, Session user',exact:true}).waitFor();
 assert.match(await blocked.locator('#b-status').innerText(),/storage is unavailable/);
 console.log('Passed profile persistence/clear/edit, birthday and normal greetings, local date change, leap-day handling, date validation, blocked-storage fallback, no profile in host snapshots, and profile responsive widths.');
 const corrupt=await browser.newPage();
 await corrupt.goto(url);
 await corrupt.evaluate(()=>localStorage.setItem('bento.prototype.workspace.v4','{"version":4,"invalid":true}'));
 await corrupt.reload();
 assert.match(await corrupt.locator('#b-status').innerText(),/left unchanged/);
 await corrupt.getByRole('button',{name:'Meeting note',exact:true}).click();
 assert.equal(await corrupt.evaluate(()=>localStorage.getItem('bento.prototype.workspace.v4')),'{"version":4,"invalid":true}');
 await corrupt.close();
 console.log('Passed invalid saved-workspace preservation.');
 // Upgrade a persisted version 3 workspace without changing IDs or its backup copy.
 const migration=await browser.newPage();
 await migration.goto(url);
 const legacy=await migration.evaluate(async()=>{
  const {default: BentoWorkspace} = await import('./workspace.js');
  const workspace=BentoWorkspace.createWorkspace({coordination:'- [ ] Legacy action\n',drainage:'# Drainage\n'});
  const task=BentoWorkspace.allTasks(workspace)[0];
  workspace.records[task.id].body='Legacy supporting notes';
  workspace.records.coordination.body=workspace.records.coordination.body.trimEnd()+' <!-- bento-ref: ref-legacy -->\n';
  workspace.records.coordination.references={'ref-legacy':{target:task.id,base_title:task.title,base_completed:false}};
  workspace.version=3;
  const saved=JSON.stringify({version:3,savedAt:1,view:'document',project:null,document:'coordination',note:'coordination',editor:'write',workspace});
  localStorage.removeItem('bento.prototype.workspace.v4');
  localStorage.setItem('bento.prototype.workspace.v3',saved);
  return {saved,id:task.id};
 });
 await migration.reload();
 await migration.getByRole('button',{name:'Open Legacy action',exact:true}).click();
 assert.match(await migration.locator('#b-reading').innerText(),/Legacy supporting notes/);
 const migrated=await migration.evaluate(()=>({current:JSON.parse(localStorage.getItem('bento.prototype.workspace.v4')),old:localStorage.getItem('bento.prototype.workspace.v3')}));
 assert.equal(migrated.old,legacy.saved);
 assert.equal(migrated.current.workspace.records[legacy.id].title,'Legacy action');
 assert.doesNotMatch(migrated.current.workspace.records.coordination.body,/bento-ref/);
 await migration.close();
 console.log('Passed saved-workspace migration with original backup, stable todo identity, and retained notes.');
 await context.close();

})().catch(e=>{console.error(e);process.exitCode=1;}).finally(async()=>{await browser?.close(); await server.close();});
